-- Medicine Substitution & Shortage Finder: ALL DDL (generated by scripts/build_submission_sql.py)
-- Educational demonstration. Synthetic data only.
-- Run on an empty MySQL 8 server as root:  mysql -u root -p < 01_DDL.sql
CREATE DATABASE IF NOT EXISTS medsub CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE medsub;
SET GLOBAL log_bin_trust_function_creators = 1;  -- needed for functions/triggers when binary logging is on

-- ============================================================================
-- 1. TABLES (CREATE TABLE: PK, FK, UNIQUE, NOT NULL, CHECK, DEFAULT, ENUM, generated column)
-- ============================================================================

-- V001: core tables (15). InnoDB, utf8mb4 (case-insensitive collation).
-- Rubric 3 (DDL): CREATE TABLE with PK, FK, UNIQUE, NOT NULL, CHECK, DEFAULT, ENUM, generated-column unique key.

CREATE TABLE IF NOT EXISTS users (
  id            INT AUTO_INCREMENT PRIMARY KEY,
  email         VARCHAR(190) NOT NULL,
  full_name     VARCHAR(120) NOT NULL,
  role          ENUM('patient','pharmacist','admin') NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  is_active     TINYINT(1) NOT NULL DEFAULT 1,
  created_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_users_email UNIQUE (email),
  CONSTRAINT chk_users_email CHECK (email LIKE '%_@_%'),
  CONSTRAINT chk_users_active CHECK (is_active IN (0,1))
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS pharmacies (
  id      INT AUTO_INCREMENT PRIMARY KEY,
  name    VARCHAR(120) NOT NULL,
  city    VARCHAR(80)  NOT NULL,
  address VARCHAR(200) NULL,
  CONSTRAINT uq_pharmacies_name UNIQUE (name)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS pharmacist_assignments (
  id          INT AUTO_INCREMENT PRIMARY KEY,
  user_id     INT NOT NULL,
  pharmacy_id INT NOT NULL,
  CONSTRAINT uq_assignment_user UNIQUE (user_id),
  CONSTRAINT fk_assign_user FOREIGN KEY (user_id) REFERENCES users(id),
  CONSTRAINT fk_assign_pharmacy FOREIGN KEY (pharmacy_id) REFERENCES pharmacies(id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS medicine_categories (
  id        INT AUTO_INCREMENT PRIMARY KEY,
  name      VARCHAR(100) NOT NULL,
  parent_id INT NULL,
  CONSTRAINT uq_category UNIQUE (parent_id, name),
  CONSTRAINT fk_category_parent FOREIGN KEY (parent_id) REFERENCES medicine_categories(id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS active_ingredients (
  id   INT AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(100) NOT NULL,
  CONSTRAINT uq_ingredient_name UNIQUE (name)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS medicines (
  id                    INT AUTO_INCREMENT PRIMARY KEY,
  name                  VARCHAR(150) NOT NULL,
  brand                 VARCHAR(100) NOT NULL,
  category_id           INT NOT NULL,
  dosage_form           ENUM('tablet','capsule','syrup','injection','ointment') NOT NULL,
  route                 ENUM('oral','topical','injection') NOT NULL DEFAULT 'oral',
  release_type          ENUM('immediate','extended') NOT NULL DEFAULT 'immediate',
  strength_basis        ENUM('per tablet','per capsule','per 5 ml','per ml','per gram') NOT NULL,
  requires_prescription TINYINT(1) NOT NULL DEFAULT 0,
  substitution_allowed  TINYINT(1) NOT NULL DEFAULT 1,
  is_active             TINYINT(1) NOT NULL DEFAULT 1,
  created_at            TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at            TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT uq_medicines_name UNIQUE (name),
  CONSTRAINT fk_medicines_category FOREIGN KEY (category_id) REFERENCES medicine_categories(id),
  CONSTRAINT chk_med_flags CHECK (requires_prescription IN (0,1) AND substitution_allowed IN (0,1) AND is_active IN (0,1))
) ENGINE=InnoDB;

-- M:N between medicines and ingredients; strength is normalised to mg, in the basis of the medicine.
CREATE TABLE IF NOT EXISTS medicine_ingredients (
  medicine_id   INT NOT NULL,
  ingredient_id INT NOT NULL,
  strength_mg   DECIMAL(10,3) NOT NULL,
  PRIMARY KEY (medicine_id, ingredient_id),
  CONSTRAINT fk_mi_medicine FOREIGN KEY (medicine_id) REFERENCES medicines(id) ON DELETE CASCADE,
  CONSTRAINT fk_mi_ingredient FOREIGN KEY (ingredient_id) REFERENCES active_ingredients(id),
  CONSTRAINT chk_mi_strength CHECK (strength_mg > 0)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS shortage_entries (
  id          INT AUTO_INCREMENT PRIMARY KEY,
  medicine_id INT NOT NULL,
  status      ENUM('OPEN','RESOLVED') NOT NULL DEFAULT 'OPEN',
  reported_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  resolved_at DATETIME NULL,
  source      ENUM('demo') NOT NULL DEFAULT 'demo',
  note        VARCHAR(200) NULL,
  CONSTRAINT fk_shortage_medicine FOREIGN KEY (medicine_id) REFERENCES medicines(id),
  CONSTRAINT chk_shortage_dates CHECK (resolved_at IS NULL OR resolved_at >= reported_at)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS inventory (
  pharmacy_id   INT NOT NULL,
  medicine_id   INT NOT NULL,
  quantity      INT NOT NULL DEFAULT 0,
  reorder_level INT NOT NULL DEFAULT 10,
  updated_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (pharmacy_id, medicine_id),
  CONSTRAINT fk_inv_pharmacy FOREIGN KEY (pharmacy_id) REFERENCES pharmacies(id),
  CONSTRAINT fk_inv_medicine FOREIGN KEY (medicine_id) REFERENCES medicines(id),
  CONSTRAINT chk_inv_qty CHECK (quantity >= 0),
  CONSTRAINT chk_inv_reorder CHECK (reorder_level >= 0)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS orders (
  id                INT AUTO_INCREMENT PRIMARY KEY,
  patient_id        INT NOT NULL,
  pharmacy_id       INT NOT NULL,
  status            ENUM('REQUESTED','UNDER_REVIEW','APPROVED','REJECTED','COMPLETED','CANCELLED') NOT NULL DEFAULT 'REQUESTED',
  prescription_note VARCHAR(500) NULL,
  created_at        TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at        TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_orders_patient FOREIGN KEY (patient_id) REFERENCES users(id),
  CONSTRAINT fk_orders_pharmacy FOREIGN KEY (pharmacy_id) REFERENCES pharmacies(id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS order_items (
  id                     INT AUTO_INCREMENT PRIMARY KEY,
  order_id               INT NOT NULL,
  requested_medicine_id  INT NOT NULL,
  dispensed_medicine_id  INT NULL,
  quantity               INT NOT NULL,
  CONSTRAINT fk_oi_order FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE,
  CONSTRAINT fk_oi_requested FOREIGN KEY (requested_medicine_id) REFERENCES medicines(id),
  CONSTRAINT fk_oi_dispensed FOREIGN KEY (dispensed_medicine_id) REFERENCES medicines(id),
  CONSTRAINT chk_oi_qty CHECK (quantity > 0)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS inventory_movements (
  id            INT AUTO_INCREMENT PRIMARY KEY,
  pharmacy_id   INT NOT NULL,
  medicine_id   INT NOT NULL,
  movement_type ENUM('RECEIPT','SALE','ADJUSTMENT') NOT NULL,
  delta         INT NOT NULL,
  batch_no      VARCHAR(40) NULL,
  expiry_date   DATE NULL,
  order_id      INT NULL,
  actor_user_id INT NOT NULL,
  note          VARCHAR(200) NULL,
  created_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_mov_inventory FOREIGN KEY (pharmacy_id, medicine_id) REFERENCES inventory(pharmacy_id, medicine_id),
  CONSTRAINT fk_mov_order FOREIGN KEY (order_id) REFERENCES orders(id),
  CONSTRAINT fk_mov_actor FOREIGN KEY (actor_user_id) REFERENCES users(id),
  CONSTRAINT chk_mov_delta CHECK (delta <> 0)
) ENGINE=InnoDB;

-- Only ONE open alert per pharmacy+medicine. MySQL has no partial indexes, so a generated column is
-- NULL while the alert is closed (UNIQUE ignores NULLs) and 'pharmacy-medicine' while it is open.
CREATE TABLE IF NOT EXISTS low_stock_alerts (
  id               INT AUTO_INCREMENT PRIMARY KEY,
  pharmacy_id      INT NOT NULL,
  medicine_id      INT NOT NULL,
  status           ENUM('OPEN','RESOLVED') NOT NULL DEFAULT 'OPEN',
  quantity_at_open INT NOT NULL,
  opened_at        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  resolved_at      DATETIME NULL,
  open_alert_key   VARCHAR(40) GENERATED ALWAYS AS (IF(status = 'OPEN', CONCAT(pharmacy_id, '-', medicine_id), NULL)) STORED,
  CONSTRAINT uq_one_open_alert UNIQUE (open_alert_key),
  CONSTRAINT fk_alert_inventory FOREIGN KEY (pharmacy_id, medicine_id) REFERENCES inventory(pharmacy_id, medicine_id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS substitution_reviews (
  id                   INT AUTO_INCREMENT PRIMARY KEY,
  order_item_id        INT NOT NULL,
  proposed_medicine_id INT NOT NULL,
  reviewer_id          INT NOT NULL,
  decision             ENUM('APPROVED','REJECTED') NOT NULL,
  decided_at           DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  note                 VARCHAR(300) NULL,
  eligibility_reason   VARCHAR(300) NOT NULL,
  ranking_snapshot     JSON NULL,
  CONSTRAINT fk_sr_item FOREIGN KEY (order_item_id) REFERENCES order_items(id) ON DELETE CASCADE,
  CONSTRAINT fk_sr_medicine FOREIGN KEY (proposed_medicine_id) REFERENCES medicines(id),
  CONSTRAINT fk_sr_reviewer FOREIGN KEY (reviewer_id) REFERENCES users(id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS sync_outbox (
  id           INT AUTO_INCREMENT PRIMARY KEY,
  operation    VARCHAR(40) NOT NULL,
  entity_id    VARCHAR(80) NOT NULL,
  payload      JSON NOT NULL,
  status       ENUM('PENDING','DONE','FAILED') NOT NULL DEFAULT 'PENDING',
  attempts     INT NOT NULL DEFAULT 0,
  last_error   VARCHAR(500) NULL,
  created_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  processed_at DATETIME NULL,
  CONSTRAINT chk_outbox_op CHECK (operation IN ('UPSERT_INVENTORY_FEED','APPEND_FEED_EVENT')),
  CONSTRAINT chk_outbox_attempts CHECK (attempts >= 0)
) ENGINE=InnoDB;


-- ============================================================================
-- 2. ALTER TABLE (added CHECKs, indexes, a new column)
-- ============================================================================

-- V002: ALTER TABLE examples (rubric 3). Applied once; recorded in schema_migrations.
ALTER TABLE medicines ADD CONSTRAINT chk_med_name_nonblank CHECK (CHAR_LENGTH(TRIM(name)) > 0);
ALTER TABLE medicines ADD INDEX idx_medicines_category (category_id);
ALTER TABLE orders ADD INDEX idx_orders_pharmacy_status (pharmacy_id, status);
ALTER TABLE sync_outbox ADD INDEX idx_outbox_status_id (status, id);
ALTER TABLE inventory_movements ADD CONSTRAINT chk_mov_sign CHECK (
  (movement_type = 'SALE' AND delta < 0) OR (movement_type = 'RECEIPT' AND delta > 0) OR movement_type = 'ADJUSTMENT');
ALTER TABLE shortage_entries ADD COLUMN severity ENUM('LOW','MEDIUM','HIGH') NOT NULL DEFAULT 'MEDIUM' AFTER status;
ALTER TABLE low_stock_alerts ADD INDEX idx_alert_status (status);


-- ============================================================================
-- 3. HELPER FUNCTIONS AND GUARD PROCEDURES (request context, availability band)
-- ============================================================================

-- R__10: request-context functions, availability band function, internal guard procedures.
-- The backend sets @app_user_id / @app_role / @app_pharmacy_id from the VERIFIED identity (never from the browser).
-- Routines read them through these functions. Guards are internal (not granted to any role).

DROP FUNCTION IF EXISTS fn_ctx_user_id;
DROP FUNCTION IF EXISTS fn_ctx_role;
DROP FUNCTION IF EXISTS fn_ctx_pharmacy_id;
DROP FUNCTION IF EXISTS fn_availability_band;
DROP PROCEDURE IF EXISTS sp_require_authenticated;
DROP PROCEDURE IF EXISTS sp_require_role;
DROP PROCEDURE IF EXISTS sp_require_pharmacy_access;

CREATE FUNCTION fn_ctx_user_id() RETURNS INT
  NOT DETERMINISTIC NO SQL SQL SECURITY DEFINER
  RETURN @app_user_id;

CREATE FUNCTION fn_ctx_role() RETURNS VARCHAR(20)
  NOT DETERMINISTIC NO SQL SQL SECURITY DEFINER
  RETURN @app_role;

CREATE FUNCTION fn_ctx_pharmacy_id() RETURNS INT
  NOT DETERMINISTIC NO SQL SQL SECURITY DEFINER
  RETURN @app_pharmacy_id;

-- Rubric 8: stored function. Patient-safe availability band (never the exact quantity).
CREATE FUNCTION fn_availability_band(p_quantity INT, p_reorder_level INT) RETURNS VARCHAR(10)
  DETERMINISTIC NO SQL SQL SECURITY DEFINER
  RETURN CASE WHEN p_quantity IS NULL OR p_quantity <= 0 THEN 'Out'
              WHEN p_quantity <= p_reorder_level THEN 'Low'
              ELSE 'In stock' END;

DELIMITER $$

CREATE PROCEDURE sp_require_authenticated()
  SQL SECURITY DEFINER
BEGIN
  IF fn_ctx_role() IS NULL OR fn_ctx_user_id() IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45401, MESSAGE_TEXT = 'Not authenticated: no request context';
  END IF;
END$$

CREATE PROCEDURE sp_require_role(IN p_role_a VARCHAR(20), IN p_role_b VARCHAR(20))
  SQL SECURITY DEFINER
BEGIN
  IF COALESCE(fn_ctx_role() IN (p_role_a, COALESCE(p_role_b, '')), 0) = 0 OR fn_ctx_user_id() IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45403, MESSAGE_TEXT = 'Access denied: role not permitted for this operation';
  END IF;
END$$

-- Pharmacists may touch only their assigned pharmacy. Admin passes only if p_allow_admin = 1.
CREATE PROCEDURE sp_require_pharmacy_access(IN p_pharmacy_id INT, IN p_allow_admin TINYINT)
  SQL SECURITY DEFINER
BEGIN
  IF COALESCE(
       (fn_ctx_role() = 'admin' AND p_allow_admin = 1)
       OR (fn_ctx_role() = 'pharmacist' AND fn_ctx_pharmacy_id() = p_pharmacy_id), 0) = 0 THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45403, MESSAGE_TEXT = 'Access denied: not allowed for this pharmacy';
  END IF;
END$$

DELIMITER ;


-- ============================================================================
-- 4. VIEWS (patient-safe availability, scoped stock views, substitution eligibility)
-- ============================================================================

-- R__20: views. All run as the definer, so roles can read them without direct table access.

CREATE OR REPLACE SQL SECURITY DEFINER VIEW v_availability AS
SELECT i.pharmacy_id, p.name AS pharmacy_name, i.medicine_id,
       fn_availability_band(i.quantity, i.reorder_level) AS availability
FROM inventory i
JOIN pharmacies p ON p.id = i.pharmacy_id
JOIN medicines m ON m.id = i.medicine_id AND m.is_active = 1;

CREATE OR REPLACE SQL SECURITY DEFINER VIEW v_users_public AS
SELECT u.id, u.email, u.full_name, u.role, u.is_active, u.created_at, pa.pharmacy_id
FROM users u LEFT JOIN pharmacist_assignments pa ON pa.user_id = u.id;

-- Exact stock: pharmacists see their own pharmacy, admin sees all, everyone else sees nothing.
CREATE OR REPLACE SQL SECURITY DEFINER VIEW v_my_inventory AS
SELECT i.pharmacy_id, p.name AS pharmacy_name, i.medicine_id, m.name AS medicine_name, m.brand,
       i.quantity, i.reorder_level, fn_availability_band(i.quantity, i.reorder_level) AS availability, i.updated_at
FROM inventory i
JOIN pharmacies p ON p.id = i.pharmacy_id
JOIN medicines m ON m.id = i.medicine_id
WHERE fn_ctx_role() = 'admin' OR (fn_ctx_role() = 'pharmacist' AND i.pharmacy_id = fn_ctx_pharmacy_id());

CREATE OR REPLACE SQL SECURITY DEFINER VIEW v_my_alerts AS
SELECT a.id, a.pharmacy_id, p.name AS pharmacy_name, a.medicine_id, m.name AS medicine_name,
       a.status, a.quantity_at_open, a.opened_at, a.resolved_at
FROM low_stock_alerts a
JOIN pharmacies p ON p.id = a.pharmacy_id
JOIN medicines m ON m.id = a.medicine_id
WHERE fn_ctx_role() = 'admin' OR (fn_ctx_role() = 'pharmacist' AND a.pharmacy_id = fn_ctx_pharmacy_id());

CREATE OR REPLACE SQL SECURITY DEFINER VIEW v_my_movements AS
SELECT mv.id, mv.pharmacy_id, mv.medicine_id, m.name AS medicine_name, mv.movement_type, mv.delta,
       mv.batch_no, mv.expiry_date, mv.order_id, mv.actor_user_id, mv.note, mv.created_at
FROM inventory_movements mv
JOIN medicines m ON m.id = mv.medicine_id
WHERE fn_ctx_role() = 'admin' OR (fn_ctx_role() = 'pharmacist' AND mv.pharmacy_id = fn_ctx_pharmacy_id());

-- Pairwise composition checks. The ONE place that decides substitution eligibility (section 8, step 1).
-- Set equality = NOT EXISTS in both directions over (ingredient, normalised strength).
CREATE OR REPLACE SQL SECURITY DEFINER VIEW v_candidate_check AS
SELECT a.id AS requested_id, b.id AS candidate_id,
  ( NOT EXISTS (SELECT 1 FROM medicine_ingredients x WHERE x.medicine_id = a.id
                  AND NOT EXISTS (SELECT 1 FROM medicine_ingredients y WHERE y.medicine_id = b.id AND y.ingredient_id = x.ingredient_id))
    AND NOT EXISTS (SELECT 1 FROM medicine_ingredients y WHERE y.medicine_id = b.id
                  AND NOT EXISTS (SELECT 1 FROM medicine_ingredients x WHERE x.medicine_id = a.id AND x.ingredient_id = y.ingredient_id))
  ) AS ingredients_same,
  ( NOT EXISTS (SELECT 1 FROM medicine_ingredients x WHERE x.medicine_id = a.id
                  AND NOT EXISTS (SELECT 1 FROM medicine_ingredients y WHERE y.medicine_id = b.id
                                    AND y.ingredient_id = x.ingredient_id AND y.strength_mg = x.strength_mg))
    AND NOT EXISTS (SELECT 1 FROM medicine_ingredients y WHERE y.medicine_id = b.id
                  AND NOT EXISTS (SELECT 1 FROM medicine_ingredients x WHERE x.medicine_id = a.id
                                    AND x.ingredient_id = y.ingredient_id AND x.strength_mg = y.strength_mg))
  ) AS strengths_same,
  (a.strength_basis = b.strength_basis) AS basis_same,
  (a.dosage_form = b.dosage_form)       AS form_same,
  (a.route = b.route)                   AS route_same,
  (a.release_type = b.release_type)     AS release_same,
  b.is_active                           AS candidate_active,
  a.substitution_allowed                AS requested_allows,
  b.substitution_allowed                AS candidate_allows
FROM medicines a JOIN medicines b ON a.id <> b.id;

CREATE OR REPLACE SQL SECURITY DEFINER VIEW v_candidate_eligibility AS
SELECT c.*,
  (ingredients_same AND strengths_same AND basis_same AND form_same AND route_same AND release_same
   AND candidate_active AND requested_allows AND candidate_allows) AS is_eligible
FROM v_candidate_check c;


-- ============================================================================
-- 5. TRIGGERS (low-stock alerts, order status machine)
-- ============================================================================

-- R__30: triggers. MySQL triggers are per event, so the low-stock rule is one procedure
-- (sp_eval_low_stock) called by an AFTER INSERT and an AFTER UPDATE trigger on inventory.

DROP TRIGGER IF EXISTS trg_inventory_low_stock_ins;
DROP TRIGGER IF EXISTS trg_inventory_low_stock_upd;
DROP TRIGGER IF EXISTS trg_orders_status_transition;
DROP PROCEDURE IF EXISTS sp_eval_low_stock;

DELIMITER $$

-- Internal (not granted to any role). Opens an alert when quantity <= reorder_level, resolves it otherwise.
CREATE PROCEDURE sp_eval_low_stock(IN p_pharmacy_id INT, IN p_medicine_id INT, IN p_quantity INT, IN p_reorder_level INT)
  SQL SECURITY DEFINER
BEGIN
  DECLARE CONTINUE HANDLER FOR 1062 BEGIN END;   -- unique open-alert key: a concurrent insert already opened it
  IF p_quantity <= p_reorder_level THEN
    INSERT INTO low_stock_alerts (pharmacy_id, medicine_id, status, quantity_at_open)
    SELECT p_pharmacy_id, p_medicine_id, 'OPEN', p_quantity FROM DUAL
    WHERE NOT EXISTS (SELECT 1 FROM low_stock_alerts
                      WHERE pharmacy_id = p_pharmacy_id AND medicine_id = p_medicine_id AND status = 'OPEN');
  ELSE
    UPDATE low_stock_alerts SET status = 'RESOLVED', resolved_at = NOW()
    WHERE pharmacy_id = p_pharmacy_id AND medicine_id = p_medicine_id AND status = 'OPEN';
  END IF;
END$$

CREATE TRIGGER trg_inventory_low_stock_ins AFTER INSERT ON inventory FOR EACH ROW
BEGIN
  CALL sp_eval_low_stock(NEW.pharmacy_id, NEW.medicine_id, NEW.quantity, NEW.reorder_level);
END$$

CREATE TRIGGER trg_inventory_low_stock_upd AFTER UPDATE ON inventory FOR EACH ROW
BEGIN
  CALL sp_eval_low_stock(NEW.pharmacy_id, NEW.medicine_id, NEW.quantity, NEW.reorder_level);
END$$

-- Order status machine: REQUESTED -> UNDER_REVIEW -> APPROVED | REJECTED ; APPROVED -> COMPLETED ;
-- CANCELLED from any non-terminal state. COMPLETED / REJECTED / CANCELLED are terminal.
CREATE TRIGGER trg_orders_status_transition BEFORE UPDATE ON orders FOR EACH ROW
BEGIN
  IF NEW.status <> OLD.status THEN
    IF NOT ( (OLD.status = 'REQUESTED'    AND NEW.status IN ('UNDER_REVIEW', 'CANCELLED'))
          OR (OLD.status = 'UNDER_REVIEW' AND NEW.status IN ('APPROVED', 'REJECTED', 'CANCELLED'))
          OR (OLD.status = 'APPROVED'     AND NEW.status IN ('COMPLETED', 'CANCELLED')) ) THEN
      SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45409, MESSAGE_TEXT = 'Invalid order status transition';
    END IF;
  END IF;
END$$

DELIMITER ;


-- ============================================================================
-- 6. STORED PROCEDURES: substitution candidates
-- ============================================================================

-- R__40: substitution-candidate procedures (section 8). All structured eligibility lives in v_candidate_eligibility.
-- Pipeline: (1) eligibility  (2) ranking of eligible candidates  (3) pharmacist decision (R__50).
-- MySQL has no table-returning functions, so these are procedures that return result sets.

DROP PROCEDURE IF EXISTS sp_equivalent_candidates;
DROP PROCEDURE IF EXISTS sp_candidate_rejections;
DROP PROCEDURE IF EXISTS sp_rank_candidates;

DELIMITER $$

-- Rubric 8: procedure. Identical ingredient set and strengths, same form/route/release, active, substitution allowed.
CREATE PROCEDURE sp_equivalent_candidates(IN p_medicine_id INT)
  SQL SECURITY DEFINER
BEGIN
  CALL sp_require_authenticated();
  SELECT m.id AS medicine_id, m.name, m.brand, m.dosage_form, m.route, m.release_type, m.requires_prescription,
         'Same active ingredients and strengths, dosage form, route and release type' AS eligibility_reason,
         'PENDING_PHARMACIST_VERIFICATION' AS verification_status
  FROM v_candidate_eligibility e
  JOIN medicines m ON m.id = e.candidate_id
  WHERE e.requested_id = p_medicine_id AND e.is_eligible = 1
  ORDER BY m.name;
END$$

-- Near-misses (same category or sharing an ingredient) with a human-readable reason for every failed rule.
CREATE PROCEDURE sp_candidate_rejections(IN p_medicine_id INT)
  SQL SECURITY DEFINER
BEGIN
  CALL sp_require_authenticated();
  SELECT m.id AS medicine_id, m.name, m.brand,
         CONCAT_WS('; ',
           IF(e.ingredients_same = 0, 'different active-ingredient set', NULL),
           IF(e.ingredients_same = 1 AND e.strengths_same = 0, 'different strength', NULL),
           IF(e.basis_same = 0, 'different strength basis', NULL),
           IF(e.form_same = 0, 'different dosage form', NULL),
           IF(e.route_same = 0, 'different route', NULL),
           IF(e.release_same = 0, 'different release type', NULL),
           IF(e.candidate_active = 0, 'candidate is inactive or discontinued', NULL),
           IF(e.requested_allows = 0, 'substitution not allowed for the requested medicine', NULL),
           IF(e.candidate_allows = 0, 'substitution not allowed for this medicine', NULL)) AS reject_reason
  FROM v_candidate_eligibility e
  JOIN medicines m ON m.id = e.candidate_id
  WHERE e.requested_id = p_medicine_id AND e.is_eligible = 0
    AND ( m.category_id = (SELECT r.category_id FROM medicines r WHERE r.id = p_medicine_id)
          OR EXISTS (SELECT 1 FROM medicine_ingredients x JOIN medicine_ingredients y ON y.ingredient_id = x.ingredient_id
                     WHERE x.medicine_id = p_medicine_id AND y.medicine_id = m.id) )
  ORDER BY m.name;
END$$

-- Ranking of ELIGIBLE candidates only (never changes eligibility):
--   stocked at the chosen pharmacy first, then higher total quantity, then fewer open low-stock alerts, then name.
-- Exact quantities are returned only to an admin or to the pharmacist of p_pharmacy_id; everyone else gets bands.
CREATE PROCEDURE sp_rank_candidates(IN p_medicine_id INT, IN p_pharmacy_id INT)
  SQL SECURITY DEFINER
BEGIN
  DECLARE v_role VARCHAR(20);
  DECLARE v_exact_here TINYINT DEFAULT 0;
  CALL sp_require_authenticated();
  SET v_role = fn_ctx_role();
  SET v_exact_here = COALESCE(v_role = 'admin' OR (v_role = 'pharmacist' AND p_pharmacy_id = fn_ctx_pharmacy_id()), 0);

  SELECT ROW_NUMBER() OVER (ORDER BY (COALESCE(h.quantity, 0) > 0) DESC, COALESCE(tot.total_qty, 0) DESC,
                                     COALESCE(al.open_alerts, 0), m.name) AS rank_position,
         m.id AS medicine_id, m.name, m.brand, m.requires_prescription,
         fn_availability_band(COALESCE(h.quantity, 0), COALESCE(h.reorder_level, 0)) AS availability_here,
         IF(v_exact_here = 1, COALESCE(h.quantity, 0), NULL) AS quantity_here,
         COALESCE(tot.pharmacies_stocking, 0) AS pharmacies_stocking,
         IF(v_role = 'admin', COALESCE(tot.total_qty, 0), NULL) AS total_quantity,
         COALESCE(al.open_alerts, 0) AS open_low_stock_alerts,
         'Same active ingredients and strengths, dosage form, route and release type' AS eligibility_reason,
         'PENDING_PHARMACIST_VERIFICATION' AS verification_status
  FROM v_candidate_eligibility e
  JOIN medicines m ON m.id = e.candidate_id
  LEFT JOIN inventory h ON h.medicine_id = m.id AND h.pharmacy_id = p_pharmacy_id
  LEFT JOIN (SELECT medicine_id, SUM(quantity) AS total_qty, SUM(quantity > 0) AS pharmacies_stocking
             FROM inventory GROUP BY medicine_id) tot ON tot.medicine_id = m.id
  LEFT JOIN (SELECT medicine_id, COUNT(*) AS open_alerts
             FROM low_stock_alerts WHERE status = 'OPEN' GROUP BY medicine_id) al ON al.medicine_id = m.id
  WHERE e.requested_id = p_medicine_id AND e.is_eligible = 1
  ORDER BY rank_position;
END$$

DELIMITER ;


-- ============================================================================
-- 7. STORED PROCEDURES: workflow, sale transaction, outbox, admin
-- ============================================================================

-- R__50: guarded workflow procedures. All SQL SECURITY DEFINER; each checks the trusted request context.
-- Error numbers: 45401 unauthenticated, 45403 forbidden, 45404 not found, 45409 conflict, 45422 invalid input.

DROP PROCEDURE IF EXISTS sp_auth_lookup;
DROP PROCEDURE IF EXISTS sp_auth_identity;
DROP PROCEDURE IF EXISTS sp_write_outbox;
DROP PROCEDURE IF EXISTS sp_receive_stock;
DROP PROCEDURE IF EXISTS sp_adjust_stock;
DROP PROCEDURE IF EXISTS sp_set_reorder_level;
DROP PROCEDURE IF EXISTS sp_create_my_order;
DROP PROCEDURE IF EXISTS sp_list_my_orders;
DROP PROCEDURE IF EXISTS sp_list_pharmacy_orders;
DROP PROCEDURE IF EXISTS sp_list_reviews;
DROP PROCEDURE IF EXISTS sp_cancel_order;
DROP PROCEDURE IF EXISTS sp_start_review;
DROP PROCEDURE IF EXISTS sp_decide_substitution;
DROP PROCEDURE IF EXISTS sp_approve_order;
DROP PROCEDURE IF EXISTS sp_reject_order;
DROP PROCEDURE IF EXISTS sp_complete_order;
DROP PROCEDURE IF EXISTS sp_enqueue_full_resync;
DROP PROCEDURE IF EXISTS sp_admin_create_user;
DROP PROCEDURE IF EXISTS sp_admin_assign_pharmacist;
DROP PROCEDURE IF EXISTS sp_admin_set_user_active;

DELIMITER $$

-- ---------------------------------------------------------------- authentication lookups (auth account only)
CREATE PROCEDURE sp_auth_lookup(IN p_email VARCHAR(190))
  SQL SECURITY DEFINER
BEGIN
  SELECT id, role, password_hash, is_active FROM users WHERE email = p_email;
END$$

CREATE PROCEDURE sp_auth_identity(IN p_user_id INT)
  SQL SECURITY DEFINER
BEGIN
  SELECT u.id, u.email, u.full_name, u.role, u.is_active, pa.pharmacy_id
  FROM users u LEFT JOIN pharmacist_assignments pa ON pa.user_id = u.id
  WHERE u.id = p_user_id;
END$$

-- ---------------------------------------------------------------- outbox (internal; same transaction as the change)
-- Contract with MongoDB (docs/NOSQL.md): two rows per stock change.
CREATE PROCEDURE sp_write_outbox(IN p_pharmacy_id INT, IN p_medicine_id INT, IN p_source VARCHAR(20),
    IN p_movement_id INT, IN p_delta INT, IN p_order_id INT, IN p_batch_no VARCHAR(40), IN p_expiry DATE)
  SQL SECURITY DEFINER
BEGIN
  DECLARE v_qty INT;
  DECLARE v_reorder INT;
  DECLARE v_now VARCHAR(19);
  SELECT quantity, reorder_level INTO v_qty, v_reorder
  FROM inventory WHERE pharmacy_id = p_pharmacy_id AND medicine_id = p_medicine_id;
  SET v_now = DATE_FORMAT(UTC_TIMESTAMP(), '%Y-%m-%dT%H:%i:%s');
  INSERT INTO sync_outbox (operation, entity_id, payload) VALUES
    ('UPSERT_INVENTORY_FEED', CONCAT('ph', p_pharmacy_id, ':med', p_medicine_id),
     JSON_OBJECT('pharmacy_id', p_pharmacy_id, 'medicine_id', p_medicine_id, 'quantity', v_qty,
                 'reorder_level', v_reorder, 'availability', fn_availability_band(v_qty, v_reorder),
                 'low_stock', IF(v_qty <= v_reorder, CAST('true' AS JSON), CAST('false' AS JSON)),
                 'source', p_source, 'occurred_at', v_now,
                 'metadata', JSON_OBJECT('last_batch_no', p_batch_no, 'last_expiry_date', p_expiry)));
  -- p_movement_id = 0 means "no ledger movement" (e.g. reorder-level change): only the document upsert is needed
  IF p_movement_id > 0 THEN
    INSERT INTO sync_outbox (operation, entity_id, payload) VALUES
      ('APPEND_FEED_EVENT', CONCAT(p_source, ':', p_movement_id),
       JSON_OBJECT('source', p_source, 'pharmacy_id', p_pharmacy_id, 'medicine_id', p_medicine_id,
                   'delta', p_delta, 'order_id', p_order_id, 'quantity_after', v_qty, 'occurred_at', v_now,
                   'details', JSON_OBJECT('batch_no', p_batch_no, 'expiry_date', p_expiry)));
  END IF;
END$$

-- ---------------------------------------------------------------- stock
CREATE PROCEDURE sp_receive_stock(IN p_pharmacy_id INT, IN p_medicine_id INT, IN p_quantity INT,
    IN p_batch_no VARCHAR(40), IN p_expiry DATE)
  SQL SECURITY DEFINER
BEGIN
  DECLARE v_mov INT;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  CALL sp_require_pharmacy_access(p_pharmacy_id, 1);
  IF p_quantity IS NULL OR p_quantity <= 0 THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45422, MESSAGE_TEXT = 'Received quantity must be positive';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM medicines WHERE id = p_medicine_id AND is_active = 1)
     OR NOT EXISTS (SELECT 1 FROM pharmacies WHERE id = p_pharmacy_id) THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45404, MESSAGE_TEXT = 'Medicine or pharmacy not found';
  END IF;
  START TRANSACTION;
  INSERT INTO inventory (pharmacy_id, medicine_id, quantity) VALUES (p_pharmacy_id, p_medicine_id, p_quantity) AS n
    ON DUPLICATE KEY UPDATE quantity = inventory.quantity + n.quantity;
  INSERT INTO inventory_movements (pharmacy_id, medicine_id, movement_type, delta, batch_no, expiry_date, actor_user_id)
    VALUES (p_pharmacy_id, p_medicine_id, 'RECEIPT', p_quantity, p_batch_no, p_expiry, fn_ctx_user_id());
  SET v_mov = LAST_INSERT_ID();
  CALL sp_write_outbox(p_pharmacy_id, p_medicine_id, 'receipt', v_mov, p_quantity, NULL, p_batch_no, p_expiry);
  COMMIT;
  SELECT quantity, reorder_level FROM inventory WHERE pharmacy_id = p_pharmacy_id AND medicine_id = p_medicine_id;
END$$

CREATE PROCEDURE sp_adjust_stock(IN p_pharmacy_id INT, IN p_medicine_id INT, IN p_delta INT, IN p_note VARCHAR(200))
  SQL SECURITY DEFINER
BEGIN
  DECLARE v_qty INT;
  DECLARE v_mov INT;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  CALL sp_require_pharmacy_access(p_pharmacy_id, 1);
  IF p_delta IS NULL OR p_delta = 0 THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45422, MESSAGE_TEXT = 'Adjustment must be non-zero';
  END IF;
  START TRANSACTION;
  SELECT quantity INTO v_qty FROM inventory WHERE pharmacy_id = p_pharmacy_id AND medicine_id = p_medicine_id FOR UPDATE;
  IF v_qty IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45404, MESSAGE_TEXT = 'No inventory row for this pharmacy and medicine';
  END IF;
  IF v_qty + p_delta < 0 THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45409, MESSAGE_TEXT = 'Adjustment would make stock negative';
  END IF;
  UPDATE inventory SET quantity = quantity + p_delta WHERE pharmacy_id = p_pharmacy_id AND medicine_id = p_medicine_id;
  INSERT INTO inventory_movements (pharmacy_id, medicine_id, movement_type, delta, note, actor_user_id)
    VALUES (p_pharmacy_id, p_medicine_id, 'ADJUSTMENT', p_delta, p_note, fn_ctx_user_id());
  SET v_mov = LAST_INSERT_ID();
  CALL sp_write_outbox(p_pharmacy_id, p_medicine_id, 'adjustment', v_mov, p_delta, NULL, NULL, NULL);
  COMMIT;
  SELECT quantity, reorder_level FROM inventory WHERE pharmacy_id = p_pharmacy_id AND medicine_id = p_medicine_id;
END$$

CREATE PROCEDURE sp_set_reorder_level(IN p_pharmacy_id INT, IN p_medicine_id INT, IN p_level INT)
  SQL SECURITY DEFINER
BEGIN
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  CALL sp_require_pharmacy_access(p_pharmacy_id, 1);
  IF p_level IS NULL OR p_level < 0 THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45422, MESSAGE_TEXT = 'Reorder level must be >= 0';
  END IF;
  START TRANSACTION;
  UPDATE inventory SET reorder_level = p_level WHERE pharmacy_id = p_pharmacy_id AND medicine_id = p_medicine_id;
  IF ROW_COUNT() = 0 AND NOT EXISTS (SELECT 1 FROM inventory WHERE pharmacy_id = p_pharmacy_id AND medicine_id = p_medicine_id) THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45404, MESSAGE_TEXT = 'No inventory row for this pharmacy and medicine';
  END IF;
  CALL sp_write_outbox(p_pharmacy_id, p_medicine_id, 'adjustment', 0, 0, NULL, NULL, NULL);
  COMMIT;
  SELECT quantity, reorder_level FROM inventory WHERE pharmacy_id = p_pharmacy_id AND medicine_id = p_medicine_id;
END$$

-- ---------------------------------------------------------------- orders (patient)
CREATE PROCEDURE sp_create_my_order(IN p_pharmacy_id INT, IN p_medicine_id INT, IN p_quantity INT, IN p_prescription_note VARCHAR(500))
  SQL SECURITY DEFINER
BEGIN
  DECLARE v_order INT;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  CALL sp_require_role('patient', NULL);
  IF p_quantity IS NULL OR p_quantity <= 0 THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45422, MESSAGE_TEXT = 'Quantity must be positive';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pharmacies WHERE id = p_pharmacy_id)
     OR NOT EXISTS (SELECT 1 FROM medicines WHERE id = p_medicine_id AND is_active = 1) THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45404, MESSAGE_TEXT = 'Medicine or pharmacy not found';
  END IF;
  START TRANSACTION;
  INSERT INTO orders (patient_id, pharmacy_id, prescription_note) VALUES (fn_ctx_user_id(), p_pharmacy_id, p_prescription_note);
  SET v_order = LAST_INSERT_ID();
  INSERT INTO order_items (order_id, requested_medicine_id, quantity) VALUES (v_order, p_medicine_id, p_quantity);
  COMMIT;
  SELECT v_order AS order_id, 'REQUESTED' AS status;
END$$

CREATE PROCEDURE sp_list_my_orders()
  SQL SECURITY DEFINER
BEGIN
  CALL sp_require_role('patient', NULL);
  SELECT o.id AS order_id, o.status, o.pharmacy_id, ph.name AS pharmacy_name, o.prescription_note, o.created_at,
         oi.id AS item_id, oi.requested_medicine_id, rm.name AS requested_name,
         oi.dispensed_medicine_id, dm.name AS dispensed_name, oi.quantity
  FROM orders o
  JOIN pharmacies ph ON ph.id = o.pharmacy_id
  JOIN order_items oi ON oi.order_id = o.id
  JOIN medicines rm ON rm.id = oi.requested_medicine_id
  LEFT JOIN medicines dm ON dm.id = oi.dispensed_medicine_id
  WHERE o.patient_id = fn_ctx_user_id()
  ORDER BY o.id DESC, oi.id;
END$$

-- ---------------------------------------------------------------- orders (pharmacist / admin read)
CREATE PROCEDURE sp_list_pharmacy_orders(IN p_status VARCHAR(20))
  SQL SECURITY DEFINER
BEGIN
  CALL sp_require_role('pharmacist', 'admin');
  SELECT o.id AS order_id, o.status, o.pharmacy_id, ph.name AS pharmacy_name, u.full_name AS patient_name,
         o.prescription_note, o.created_at,
         oi.id AS item_id, oi.requested_medicine_id, rm.name AS requested_name, rm.requires_prescription,
         oi.dispensed_medicine_id, dm.name AS dispensed_name, oi.quantity
  FROM orders o
  JOIN pharmacies ph ON ph.id = o.pharmacy_id
  JOIN users u ON u.id = o.patient_id
  JOIN order_items oi ON oi.order_id = o.id
  JOIN medicines rm ON rm.id = oi.requested_medicine_id
  LEFT JOIN medicines dm ON dm.id = oi.dispensed_medicine_id
  WHERE (p_status IS NULL OR o.status = p_status)
    AND (fn_ctx_role() = 'admin' OR o.pharmacy_id = fn_ctx_pharmacy_id())
  ORDER BY o.id DESC, oi.id;
END$$

CREATE PROCEDURE sp_list_reviews(IN p_order_id INT)
  SQL SECURITY DEFINER
BEGIN
  DECLARE v_patient INT;
  DECLARE v_pharmacy INT;
  CALL sp_require_authenticated();
  SELECT patient_id, pharmacy_id INTO v_patient, v_pharmacy FROM orders WHERE id = p_order_id;
  IF v_patient IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45404, MESSAGE_TEXT = 'Order not found';
  END IF;
  IF COALESCE(fn_ctx_role() = 'admin' OR (fn_ctx_role() = 'patient' AND v_patient = fn_ctx_user_id())
              OR (fn_ctx_role() = 'pharmacist' AND v_pharmacy = fn_ctx_pharmacy_id()), 0) = 0 THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45403, MESSAGE_TEXT = 'Access denied: not your order';
  END IF;
  SELECT r.id, r.order_item_id, r.proposed_medicine_id, m.name AS proposed_name, r.decision, r.decided_at,
         r.note, r.eligibility_reason, r.ranking_snapshot, rv.full_name AS reviewer_name
  FROM substitution_reviews r
  JOIN order_items oi ON oi.id = r.order_item_id
  JOIN medicines m ON m.id = r.proposed_medicine_id
  JOIN users rv ON rv.id = r.reviewer_id
  WHERE oi.order_id = p_order_id ORDER BY r.id;
END$$

-- ---------------------------------------------------------------- order workflow
CREATE PROCEDURE sp_cancel_order(IN p_order_id INT)
  SQL SECURITY DEFINER
BEGIN
  DECLARE v_patient INT;
  DECLARE v_pharmacy INT;
  DECLARE v_status VARCHAR(20);
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  CALL sp_require_authenticated();
  START TRANSACTION;
  SELECT patient_id, pharmacy_id, status INTO v_patient, v_pharmacy, v_status FROM orders WHERE id = p_order_id FOR UPDATE;
  IF v_status IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45404, MESSAGE_TEXT = 'Order not found';
  END IF;
  IF COALESCE(fn_ctx_role() = 'admin' OR (fn_ctx_role() = 'patient' AND v_patient = fn_ctx_user_id())
              OR (fn_ctx_role() = 'pharmacist' AND v_pharmacy = fn_ctx_pharmacy_id()), 0) = 0 THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45403, MESSAGE_TEXT = 'Access denied: not your order';
  END IF;
  UPDATE orders SET status = 'CANCELLED' WHERE id = p_order_id;   -- trigger rejects terminal states
  COMMIT;
  SELECT p_order_id AS order_id, 'CANCELLED' AS status;
END$$

CREATE PROCEDURE sp_start_review(IN p_order_id INT)
  SQL SECURITY DEFINER
BEGIN
  DECLARE v_pharmacy INT;
  DECLARE v_status VARCHAR(20);
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  START TRANSACTION;
  SELECT pharmacy_id, status INTO v_pharmacy, v_status FROM orders WHERE id = p_order_id FOR UPDATE;
  IF v_status IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45404, MESSAGE_TEXT = 'Order not found';
  END IF;
  CALL sp_require_pharmacy_access(v_pharmacy, 0);
  IF v_status <> 'REQUESTED' THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45409, MESSAGE_TEXT = 'Order is not in REQUESTED state';
  END IF;
  UPDATE orders SET status = 'UNDER_REVIEW' WHERE id = p_order_id AND status = 'REQUESTED';
  COMMIT;
  SELECT p_order_id AS order_id, 'UNDER_REVIEW' AS status;
END$$

-- The pharmacist's decision on one proposed medicine (section 8, step 3). Nothing is substituted without it.
CREATE PROCEDURE sp_decide_substitution(IN p_item_id INT, IN p_proposed_medicine_id INT,
    IN p_decision VARCHAR(10), IN p_note VARCHAR(300))
  SQL SECURITY DEFINER
BEGIN
  DECLARE v_order INT;
  DECLARE v_requested INT;
  DECLARE v_pharmacy INT;
  DECLARE v_status VARCHAR(20);
  DECLARE v_eligible INT DEFAULT 0;
  DECLARE v_reason VARCHAR(300);
  DECLARE v_band VARCHAR(10);
  DECLARE v_stocking INT;
  DECLARE v_review INT;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  IF p_decision IS NULL OR p_decision NOT IN ('APPROVED', 'REJECTED') THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45422, MESSAGE_TEXT = 'Decision must be APPROVED or REJECTED';
  END IF;
  START TRANSACTION;
  SELECT oi.order_id, oi.requested_medicine_id, o.pharmacy_id, o.status
    INTO v_order, v_requested, v_pharmacy, v_status
  FROM order_items oi JOIN orders o ON o.id = oi.order_id WHERE oi.id = p_item_id FOR UPDATE;
  IF v_order IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45404, MESSAGE_TEXT = 'Order item not found';
  END IF;
  CALL sp_require_pharmacy_access(v_pharmacy, 0);
  IF v_status <> 'UNDER_REVIEW' THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45409, MESSAGE_TEXT = 'Order is not UNDER_REVIEW';
  END IF;
  IF p_proposed_medicine_id = v_requested THEN
    SET v_eligible = 1;
    SET v_reason = 'Requested medicine itself (no substitution)';
  ELSE
    SELECT COUNT(*) INTO v_eligible FROM v_candidate_eligibility
    WHERE requested_id = v_requested AND candidate_id = p_proposed_medicine_id AND is_eligible = 1;
    SET v_reason = IF(v_eligible = 1, 'Same active ingredients and strengths, dosage form, route and release type',
                      'NOT an eligible composition match');
  END IF;
  IF p_decision = 'APPROVED' AND v_eligible = 0 THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45422, MESSAGE_TEXT = 'Proposed medicine is not an eligible composition match';
  END IF;
  SELECT fn_availability_band(COALESCE(quantity, 0), COALESCE(reorder_level, 0)) INTO v_band
  FROM inventory WHERE pharmacy_id = v_pharmacy AND medicine_id = p_proposed_medicine_id;
  SELECT COUNT(*) INTO v_stocking FROM inventory WHERE medicine_id = p_proposed_medicine_id AND quantity > 0;
  INSERT INTO substitution_reviews (order_item_id, proposed_medicine_id, reviewer_id, decision, note, eligibility_reason, ranking_snapshot)
  VALUES (p_item_id, p_proposed_medicine_id, fn_ctx_user_id(), p_decision, p_note, v_reason,
          JSON_OBJECT('pharmacy_id', v_pharmacy, 'availability_here', COALESCE(v_band, 'Out'), 'pharmacies_stocking', v_stocking));
  SET v_review = LAST_INSERT_ID();
  IF p_decision = 'APPROVED' THEN
    UPDATE order_items SET dispensed_medicine_id = p_proposed_medicine_id WHERE id = p_item_id;
  END IF;
  COMMIT;
  SELECT v_review AS review_id, p_decision AS decision, v_reason AS eligibility_reason;
END$$

CREATE PROCEDURE sp_approve_order(IN p_order_id INT)
  SQL SECURITY DEFINER
BEGIN
  DECLARE v_pharmacy INT;
  DECLARE v_status VARCHAR(20);
  DECLARE v_note VARCHAR(500);
  DECLARE v_rx INT;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  START TRANSACTION;
  SELECT pharmacy_id, status, prescription_note INTO v_pharmacy, v_status, v_note FROM orders WHERE id = p_order_id FOR UPDATE;
  IF v_status IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45404, MESSAGE_TEXT = 'Order not found';
  END IF;
  CALL sp_require_pharmacy_access(v_pharmacy, 0);
  IF v_status <> 'UNDER_REVIEW' THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45409, MESSAGE_TEXT = 'Order is not UNDER_REVIEW';
  END IF;
  -- items without a substitution decision are dispensed as requested
  UPDATE order_items SET dispensed_medicine_id = requested_medicine_id
  WHERE order_id = p_order_id AND dispensed_medicine_id IS NULL;
  SELECT COUNT(*) INTO v_rx FROM order_items oi JOIN medicines m ON m.id = oi.dispensed_medicine_id
  WHERE oi.order_id = p_order_id AND m.requires_prescription = 1;
  IF v_rx > 0 AND (v_note IS NULL OR CHAR_LENGTH(TRIM(v_note)) = 0) THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45422, MESSAGE_TEXT = 'A prescription note is required for a prescription-only medicine';
  END IF;
  UPDATE orders SET status = 'APPROVED' WHERE id = p_order_id AND status = 'UNDER_REVIEW';
  COMMIT;
  SELECT p_order_id AS order_id, 'APPROVED' AS status;
END$$

CREATE PROCEDURE sp_reject_order(IN p_order_id INT)
  SQL SECURITY DEFINER
BEGIN
  DECLARE v_pharmacy INT;
  DECLARE v_status VARCHAR(20);
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  START TRANSACTION;
  SELECT pharmacy_id, status INTO v_pharmacy, v_status FROM orders WHERE id = p_order_id FOR UPDATE;
  IF v_status IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45404, MESSAGE_TEXT = 'Order not found';
  END IF;
  CALL sp_require_pharmacy_access(v_pharmacy, 0);
  IF v_status <> 'UNDER_REVIEW' THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45409, MESSAGE_TEXT = 'Order is not UNDER_REVIEW';
  END IF;
  UPDATE orders SET status = 'REJECTED' WHERE id = p_order_id AND status = 'UNDER_REVIEW';
  COMMIT;
  SELECT p_order_id AS order_id, 'REJECTED' AS status;
END$$

-- ---------------------------------------------------------------- Rubric 8: the sale transaction
-- One transaction: lock order, lock inventory rows in primary-key order, check stock, deduct, write SALE movements
-- and outbox rows, mark COMPLETED. Any error rolls everything back. A repeat call fails the APPROVED guard.
-- Call it with no application transaction open (START TRANSACTION would implicitly commit it).
CREATE PROCEDURE sp_complete_order(IN p_order_id INT, IN p_actor INT)
  SQL SECURITY DEFINER
BEGIN
  DECLARE v_done INT DEFAULT 0;
  DECLARE v_status VARCHAR(20);
  DECLARE v_pharmacy INT;
  DECLARE v_med INT;
  DECLARE v_qty INT;
  DECLARE v_locked INT;
  DECLARE v_short INT;
  DECLARE v_mov INT;
  DECLARE cur CURSOR FOR
    SELECT COALESCE(dispensed_medicine_id, requested_medicine_id) AS med, SUM(quantity) AS qty
    FROM order_items WHERE order_id = p_order_id GROUP BY med ORDER BY med;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;

  START TRANSACTION;
  SELECT status, pharmacy_id INTO v_status, v_pharmacy FROM orders WHERE id = p_order_id FOR UPDATE;
  IF v_status IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45404, MESSAGE_TEXT = 'Order not found';
  END IF;
  CALL sp_require_pharmacy_access(v_pharmacy, 0);
  IF p_actor IS NULL OR p_actor <> fn_ctx_user_id() THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45403, MESSAGE_TEXT = 'Actor does not match the authenticated user';
  END IF;
  IF v_status <> 'APPROVED' THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45409, MESSAGE_TEXT = 'Order is not APPROVED (already completed or not ready)';
  END IF;

  -- lock inventory rows; index scan order = primary key (pharmacy_id, medicine_id) = deterministic lock order
  SELECT COUNT(*) INTO v_locked FROM inventory
  WHERE pharmacy_id = v_pharmacy
    AND medicine_id IN (SELECT COALESCE(dispensed_medicine_id, requested_medicine_id) FROM order_items WHERE order_id = p_order_id)
  FOR UPDATE;

  SELECT COUNT(*) INTO v_short
  FROM (SELECT COALESCE(dispensed_medicine_id, requested_medicine_id) AS med, SUM(quantity) AS qty
        FROM order_items WHERE order_id = p_order_id GROUP BY med) t
  LEFT JOIN inventory i ON i.pharmacy_id = v_pharmacy AND i.medicine_id = t.med
  WHERE COALESCE(i.quantity, 0) < t.qty
  FOR UPDATE;   -- locking read = CURRENT data. A plain SELECT would use the transaction snapshot taken before we
                -- waited for the row locks, and could miss a sale committed by a competing transaction meanwhile.
  IF v_short > 0 THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45409, MESSAGE_TEXT = 'Insufficient stock to complete the order';
  END IF;

  SET v_done = 0;
  OPEN cur;
  item_loop: LOOP
    FETCH cur INTO v_med, v_qty;
    IF v_done = 1 THEN LEAVE item_loop; END IF;
    UPDATE inventory SET quantity = quantity - v_qty WHERE pharmacy_id = v_pharmacy AND medicine_id = v_med;
    INSERT INTO inventory_movements (pharmacy_id, medicine_id, movement_type, delta, order_id, actor_user_id)
      VALUES (v_pharmacy, v_med, 'SALE', -v_qty, p_order_id, p_actor);
    SET v_mov = LAST_INSERT_ID();
    CALL sp_write_outbox(v_pharmacy, v_med, 'sale', v_mov, -v_qty, p_order_id, NULL, NULL);
  END LOOP;
  CLOSE cur;

  UPDATE orders SET status = 'COMPLETED' WHERE id = p_order_id AND status = 'APPROVED';
  IF ROW_COUNT() <> 1 THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45409, MESSAGE_TEXT = 'Order status changed concurrently';
  END IF;
  COMMIT;
  SELECT p_order_id AS order_id, 'COMPLETED' AS status;
END$$

-- ---------------------------------------------------------------- sync repair + admin
-- Re-enqueues every inventory row so MongoDB can be rebuilt from MySQL (the source of truth).
CREATE PROCEDURE sp_enqueue_full_resync()
  SQL SECURITY DEFINER
BEGIN
  CALL sp_require_role('admin', NULL);
  INSERT INTO sync_outbox (operation, entity_id, payload)
  SELECT 'UPSERT_INVENTORY_FEED', CONCAT('ph', i.pharmacy_id, ':med', i.medicine_id),
         JSON_OBJECT('pharmacy_id', i.pharmacy_id, 'medicine_id', i.medicine_id, 'quantity', i.quantity,
                     'reorder_level', i.reorder_level, 'availability', fn_availability_band(i.quantity, i.reorder_level),
                     'low_stock', IF(i.quantity <= i.reorder_level, CAST('true' AS JSON), CAST('false' AS JSON)),
                     'source', 'resync', 'occurred_at', DATE_FORMAT(UTC_TIMESTAMP(), '%Y-%m-%dT%H:%i:%s'),
                     'metadata', JSON_OBJECT())
  FROM inventory i;
  SELECT ROW_COUNT() AS enqueued;
END$$

CREATE PROCEDURE sp_admin_create_user(IN p_email VARCHAR(190), IN p_full_name VARCHAR(120),
    IN p_role VARCHAR(20), IN p_password_hash VARCHAR(255), IN p_pharmacy_id INT)
  SQL SECURITY DEFINER
BEGIN
  DECLARE v_id INT;
  DECLARE EXIT HANDLER FOR 1062 BEGIN ROLLBACK; SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45409, MESSAGE_TEXT = 'Email already registered'; END;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  CALL sp_require_role('admin', NULL);
  IF p_role NOT IN ('patient', 'pharmacist', 'admin') THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45422, MESSAGE_TEXT = 'Invalid role';
  END IF;
  IF p_role = 'pharmacist' AND (p_pharmacy_id IS NULL OR NOT EXISTS (SELECT 1 FROM pharmacies WHERE id = p_pharmacy_id)) THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45422, MESSAGE_TEXT = 'A pharmacist needs a valid pharmacy';
  END IF;
  START TRANSACTION;
  INSERT INTO users (email, full_name, role, password_hash) VALUES (p_email, p_full_name, p_role, p_password_hash);
  SET v_id = LAST_INSERT_ID();
  IF p_role = 'pharmacist' THEN
    INSERT INTO pharmacist_assignments (user_id, pharmacy_id) VALUES (v_id, p_pharmacy_id);
  END IF;
  COMMIT;
  SELECT v_id AS user_id;
END$$

CREATE PROCEDURE sp_admin_assign_pharmacist(IN p_user_id INT, IN p_pharmacy_id INT)
  SQL SECURITY DEFINER
BEGIN
  CALL sp_require_role('admin', NULL);
  IF NOT EXISTS (SELECT 1 FROM users WHERE id = p_user_id AND role = 'pharmacist')
     OR NOT EXISTS (SELECT 1 FROM pharmacies WHERE id = p_pharmacy_id) THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45404, MESSAGE_TEXT = 'Pharmacist or pharmacy not found';
  END IF;
  INSERT INTO pharmacist_assignments (user_id, pharmacy_id) VALUES (p_user_id, p_pharmacy_id) AS n
    ON DUPLICATE KEY UPDATE pharmacy_id = n.pharmacy_id;
  SELECT p_user_id AS user_id, p_pharmacy_id AS pharmacy_id;
END$$

CREATE PROCEDURE sp_admin_set_user_active(IN p_user_id INT, IN p_active TINYINT)
  SQL SECURITY DEFINER
BEGIN
  CALL sp_require_role('admin', NULL);
  IF p_user_id = fn_ctx_user_id() AND p_active = 0 THEN
    SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO = 45409, MESSAGE_TEXT = 'You cannot deactivate your own account';
  END IF;
  UPDATE users SET is_active = IF(p_active = 1, 1, 0) WHERE id = p_user_id;
  SELECT p_user_id AS user_id, p_active AS is_active;
END$$

DELIMITER ;


-- ============================================================================
-- 8. ROLES AND GRANTS (MySQL has no native row-level security: roles + views + definer procedures)
-- ============================================================================

CREATE ROLE IF NOT EXISTS 'app_patient_role'@'%';
CREATE ROLE IF NOT EXISTS 'app_pharmacist_role'@'%';
CREATE ROLE IF NOT EXISTS 'app_admin_role'@'%';
CREATE ROLE IF NOT EXISTS 'app_auth_role'@'%';

-- R__90: least-privilege grants to the four MySQL roles (section 6). Run by the migrator account (has GRANT OPTION).
-- MySQL has NO native row-level security. Row scoping is done by: no direct base-table access for patients and
-- pharmacists, SECURITY DEFINER views/procedures, and the trusted request context (fn_ctx_*).
-- Helper/guard routines (sp_require_*, sp_eval_low_stock, sp_write_outbox) are intentionally NOT granted to anyone.

